1271	\begin{lemma}[Formalization support for restriction to a subregister]\label{lem:cl-restriction-idem}
1272		\lean{MIPStarRE.QPBT.coordinateRestriction_coordinateRestriction}
1273		\leanok
1274		\uses{def:register-subspace}
1275		This is not a named statement of the source article; it isolates a step used in the Lean proofs of Lemma~\ref{lem:cl-kth} and Lemma~\ref{lem:cl-func-prod}. Let $S$ and $S'$ be register subspaces of $V$ with $S \subseteq S'$. Then $(x^{S'})^S = x^S$ for every $x \in V$.
1276	\end{lemma}
1277	\begin{proof}
1278		\leanok
1279		The two sides agree coordinatewise: a coordinate of $S$ is retained by both restrictions, since $S \subseteq S'$, and a coordinate outside $S$ is set to zero by both.
1280	\end{proof}
