1293	\begin{lemma}[Formalization support for the values of a supported CL function]\label{lem:cl-supported-vanishing}
1294		\lean{MIPStarRE.QPBT.CondLinearTerm.eval_eq_zero_of_not_mem}
1295		\leanok
1296		\uses{def:cl-func, def:register-subspace}
1297		This is not a named statement of the source article; it isolates a step used in the Lean proof of Lemma~\ref{lem:cl-dist-prod}. Let $S$ be a register subspace of $V$ and let $L$ be a CL function on $V$ all of whose factor spaces are contained in $S$. Then $L(x) \in S$ for every $x \in V$.
1298	\end{lemma}
1299	\begin{proof}
1300		\leanok
1301		\uses{def:cl-func}
1302		Induction on the level of $L$. The $0$-level function is the zero function. At level $\ell \ge 1$ we have $L(x) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{V_{>1}})$, where the first summand lies in $V_1 \subseteq S$ and the second lies in $S$ by the induction hypothesis, the factor spaces of $L_{>1,\,x^{L_1}}$ being contained in $S$ as well.
1303	\end{proof}
