1329	\section{Typed conditionally linear distributions}
1330	% Paper section label sec:types kept for cross-reference fidelity. Only the mathematical
1331	% typed material (typed CL functions and distributions, graph distributions) is stated
1332	% here; the typed sampler and verifier machinery of the source is outside the scope of
1333	% the mathematical development.
1334	\label{sec:types}
1335	
1336	The question distribution of the Pauli basis test is \emph{typed}: each question is a pair consisting of a type, drawn together with the other player's type from the edges of a fixed \emph{type graph}, and a question content, drawn from a CL distribution determined by the pair of types.
1337	
1338	\begin{definition}[Typed conditionally linear functions]\label{def:typed-cl-functions}
1339		\lean{MIPStarRE.QPBT.IsTypedCondLinearFamily}
1340		\leanok
1341		\uses{def:cl-func}
1342		Let $\mathcal T$ be a finite set (the \emph{type set}) and let $V$ be $\F^n$ for some integer $n \ge 0$. A \emph{$\mathcal T$-typed family of $\ell$-level conditionally linear functions} (implicitly, \emph{on $V$}) is a collection $\{L_t\}_{t \in \mathcal T}$ such that, for each $t \in \mathcal T$, $L_t$ is an $\ell$-level conditionally linear function on $V$.
1343	\end{definition}
1344	
1345	% Nonemptiness of the edge set is stated explicitly here: with E empty, m = k = 0 and the
1346	% normalization 1/(2m-k) below is undefined. The source
1347	% (references/qpbt-paper/07_types.tex:65-82) leaves this boundary hypothesis implicit.
1348	\begin{definition}[Graph distribution]\label{def:graph-distribution}
1349		\lean{MIPStarRE.QPBT.graphDistribution}
1350		\leanok
1351		Let $G = (U, E)$ be an undirected graph with vertex set $U$ and nonempty edge set $E$. Edges in $E$ are written as multisets $\{u, v\}$ of two vertices; the case $u = v$ represents a self-loop. Suppose there are $m \ge 1$ edges, $k$ of which are self-loops. Then the \emph{graph distribution $\mu_G$ of $G$} is the distribution over $U \times U$ such that for every $(u,v) \in U \times U$,
1352		\[
1353			\mu_G(u, v) =
1354			\begin{cases}
1355				1/(2m-k) & \text{if } \{u,v\} \in E\,,\\
1356				0 & \text{otherwise}\,.
1357			\end{cases}
1358		\]
1359		This is identical to the uniform distribution over ordered pairs $(u,v) \in U \times U$ such that $\{u,v\} \in E$: each edge that is not a self-loop contributes two ordered pairs, and each self-loop contributes one, whence the normalization $2m-k$.
1360	\end{definition}
1361	
1362	\begin{lemma}[Total mass of the graph distribution]\label{lem:graph-distribution-mass}
1363		\lean{MIPStarRE.QPBT.graphDistribution_isProbability}
1364		\leanok
1365		\uses{def:graph-distribution}
1366		Let $G = (U, E)$ be an undirected graph with nonempty edge set $E$. Then the graph distribution $\mu_G$ of Definition~\ref{def:graph-distribution} has total mass one, that is, $\sum_{(u,v) \in U \times U} \mu_G(u,v) = 1$.
1367	\end{lemma}
1368	\begin{proof}
1369		\leanok
1370		\uses{def:graph-distribution}
1371		The distribution $\mu_G$ is uniform on the set of ordered pairs $(u,v) \in U \times U$ with $\{u,v\} \in E$, and that set is nonempty because $E$ is: an edge $\{u,v\} \in E$ yields the ordered pair $(u,v)$. A uniform distribution on a nonempty finite set has total mass one.
1372	\end{proof}
1373	
1374	% The nonempty-edge hypothesis on G is inherited from def:graph-distribution, where it is
1375	% needed for the graph distribution mu_G to be defined; the source
1376	% (references/qpbt-paper/07_types.tex:84-93) leaves it implicit here as well.
1377	% The Lean declaration typedCLDistribution is stated for arbitrary T-indexed families of maps
1378	% on V: it carries neither a level nor the IsTypedCondLinearFamily hypotheses that this
1379	% definition imposes on L and R, so it is a strict generalization of the definition below and
1380	% the node is left unmarked, exactly as for def:cl-dist. The identifications of the two
1381	% concrete samplers with this construction are stated separately as lem:ld-question-typed-cl
1382	% and lem:pauli-question-typed-cl in Chapter chap:qpbt-test.
1383	\begin{definition}[Typed conditionally linear distributions]\label{def:typed-cl-distributions}
1384		\lean{MIPStarRE.QPBT.typedCLDistribution}
1385		\uses{def:typed-cl-functions, def:graph-distribution, def:cl-dist}
1386		Let $\mathcal T$ be a type set and let $L = \{L_u\}_{u \in \mathcal T}$ and $R = \{R_v\}_{v \in \mathcal T}$ be $\mathcal T$-typed families of conditionally linear functions on $V$. Let $G = (\mathcal T, E)$ be a graph with vertex set $\mathcal T$ and nonempty edge set $E$, so that the graph distribution $\mu_G$ of Definition~\ref{def:graph-distribution} is defined. The \emph{$(\mathcal T, G)$-typed conditionally linear distribution $\mu^G_{L,\,R}$ corresponding to $(L, R)$} is the distribution over pairs $\bigl( (u, x), (v, y) \bigr)$, where the type pair $(u,v)$ is drawn from the graph distribution $\mu_G$ and the content pair $(x,y)$ is drawn from $\mu_{L_u,\,R_v}$.
1387	\end{definition}

