171	def pauliPointBlock {P : AdmissibleParams} (W : PauliKind) (z : PauliSpace P) :
172	    Fin P.m → PauliScalar P :=
173	  match W with
174	  | .X => pauliXBlock z
175	  | .Z => pauliZBlock z
176	
177	/-- Read the low-degree register selected by a basis from an ambient Pauli
178	vector.  Lean-only coordinate plumbing for `def:pauli-question-distribution`,
179	blueprint `ch13_qpbt_test.tex:285-329`, paper origin
180	`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:964-1120`.
181	-/
182	def pauliToLd (P : AdmissibleParams) (W : PauliKind) (z : PauliSpace P) :
183	    LdSpace P.toLdParams :=
184	  fun i => match i with
185	  | .inl (.inl j) => pauliPointBlock W z j
186	  | .inl (.inr _) => pauliScalarBlock z
187	  | .inr j => pauliDirectionBlock z j
188	
189	/-- Embed a low-degree vector into the basis-selected Pauli blocks, clearing the
190	other basis and the two `r` registers.  This is Lean-only coordinate plumbing
191	for `def:pauli-question-distribution`, blueprint
192	`blueprint/src/chapter/ch13_qpbt_test.tex:285-329`, paper origin
193	`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:964-1120`.
194	-/
195	def embedLd (P : AdmissibleParams) (W : PauliKind)
196	    (u : LdSpace P.toLdParams) : PauliSpace P :=
197	  fun i => match i with
198	  | .inl (.inl (.inl (.inl (.inl j)))) =>
199	      match W with
200	      | .X => u (.inl (.inl j))
201	      | .Z => 0
202	  | .inl (.inl (.inl (.inl (.inr j)))) =>
203	      match W with
204	      | .X => 0
205	      | .Z => u (.inl (.inl j))
206	  | .inl (.inl (.inl (.inr _))) => u (.inl (.inr ()))
207	  | .inl (.inl (.inr j)) => u (.inr j)
208	  | .inl (.inr _) => 0
209	  | .inr _ => 0
210	
211	/-- The type-4 projection retaining `V_X`, `V_Z`, `V_{R_X}`, and `V_{R_Z}` from
212	`def:pauli-question-distribution`, blueprint `ch13_qpbt_test.tex:285-329`, paper
213	origin `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:964-1120`.
214	-/
215	def pauliSharedProjection {P : AdmissibleParams} (z : PauliSpace P) : PauliSpace P :=
216	  fun i => match i with
217	  | .inl (.inl (.inl (.inl (.inl j)))) => z (.inl (.inl (.inl (.inl (.inl j)))))
218	  | .inl (.inl (.inl (.inl (.inr j)))) => z (.inl (.inl (.inl (.inl (.inr j)))))
219	  | .inl (.inl (.inl (.inr _))) => 0
220	  | .inl (.inl (.inr _)) => 0
221	  | .inl (.inr _) => z (.inl (.inr ()))
222	  | .inr _ => z (.inr ())
223	
224	/-- The source level attached to each typed Pauli CL map.  This records the
225	exact levels in items 1--5 of `def:pauli-question-distribution`: point, line,
226	and diagonal maps have levels 1, 2, and 3, the Pauli map has level 0, and the
227	shared projection has level 1.  Blueprint
228	`blueprint/src/chapter/ch13_qpbt_test.tex:285-329`; paper origin
229	`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:964-1120`.
230	-/
231	def pauliCLLevel : PauliType → ℕ
232	  | .point _ => 1
233	  | .aline _ => 2
234	  | .dline _ => 3
235	  | .pauli _ => 0
236	  | .pairW _ => 1
237	  | .pair => 1
238	  | .ms _ => 1
239	
240	/-- The typed CL dispatcher.  The point/line maps are the corresponding
241	low-degree maps embedded in the selected basis block; Pair, Magic Square, and
242	Pair/W types use the shared projection; Pauli/W is the zero-level map.  This
243	is the direct finite-space form of `def:pauli-question-distribution`,
244	blueprint `ch13_qpbt_test.tex:285-329`, paper origin
245	`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:964-1120`.
246	-/
247	noncomputable def pauliCL (P : AdmissibleParams) (t : PauliType) :
248	    PauliSpace P → PauliSpace P :=
249	  match t with
250	  | .point W => fun z => embedLd P W (ldPointCL P.toLdParams (pauliToLd P W z))
251	  | .aline W => fun z => embedLd P W (ldALineCL P.toLdParams (pauliToLd P W z))
252	  | .dline W => fun z => embedLd P W (ldDLineCL P.toLdParams (pauliToLd P W z))
253	  | .pauli _ => fun _ => 0
254	  | .pairW _ => pauliSharedProjection
255	  | .pair => pauliSharedProjection
256	  | .ms _ => pauliSharedProjection
257	
258	/-- Formalization-only auxiliary: a linear map of the ambient coefficient space
259	is conditionally linear with a single level on the full register.  This is the
260	one-level case of `def:cl-func`, blueprint `blueprint/src/chapter/ch12_qpbt_games.tex:453-463`,
261	paper origin `references/qpbt-paper/05_conditionally_linear_functions.tex:35-57`. -/
262	private theorem isCondLinearOn_one_of_linear {K ι : Type*} [Field K]
263	    [Fintype ι] [DecidableEq ι] (L : (ι → K) →ₗ[K] (ι → K)) :
264	    IsCondLinearOn K Finset.univ 1 (fun x => L x) := by
265	  refine ⟨.succ Finset.univ L (fun _ i hi => absurd (Finset.mem_univ i) hi)
266	      (fun _ => .zero), ⟨Finset.subset_univ _, fun _ => trivial⟩, ?_⟩
267	  funext x
268	  have hx : coordinateRestriction (Finset.univ : Finset ι) x = x := by
269	    funext i
270	    simp [coordinateRestriction]
271	  show L (coordinateRestriction Finset.univ x) + 0 = L x
272	  rw [hx, add_zero]
273	
274	/-- Formalization-only auxiliary: extend a coefficient vector along an injective
275	reindexing of registers, setting every coordinate outside the image to zero.
276	Together with the lemmas that follow it, this supports the transport of
277	conditional linearity between the register spaces of `def:cl-func`,
278	blueprint `blueprint/src/chapter/ch12_qpbt_games.tex:453-463`,
279	paper origin `references/qpbt-paper/05_conditionally_linear_functions.tex:35-57`. -/
280	private def clExtend {K κ ι : Type*} [Zero K] (f : κ → ι) (u : κ → K) : ι → K :=
281	  Function.extend f u 0
282	
283	/-- Formalization-only auxiliary: the extension recovers the original
284	coordinates along an injective reindexing. -/
285	private theorem clExtend_apply {K κ ι : Type*} [Zero K] {f : κ → ι}
286	    (hf : Function.Injective f) (u : κ → K) (k : κ) :
287	    clExtend f u (f k) = u k :=
288	  hf.extend_apply u 0 k
289	
290	/-- Formalization-only auxiliary: the extension vanishes at any coordinate
291	outside the image of the reindexing. -/
292	private theorem clExtend_eq_zero_of_not_mem {K κ ι : Type*} [Zero K]
293	    (f : κ → ι) (u : κ → K) (i : ι) (h : ∀ k, f k ≠ i) :
294	    clExtend f u i = 0 :=
295	  Function.extend_apply' u (0 : ι → K) i
296	    (fun hex => h hex.choose hex.choose_spec)
297	
298	/-- Formalization-only auxiliary: restriction along an injective reindexing
299	inverts the extension. -/
300	private theorem clExtend_comp {K κ ι : Type*} [Zero K] {f : κ → ι}
301	    (hf : Function.Injective f) (u : κ → K) :
302	    (fun k => clExtend f u (f k)) = u :=
303	  funext fun k => clExtend_apply hf u k
304	
305	/-- Formalization-only auxiliary: the extension of the zero vector vanishes. -/
306	private theorem clExtend_zero {K κ ι : Type*} [Zero K] {f : κ → ι}
307	    (hf : Function.Injective f) : clExtend f (0 : κ → K) = 0 := by
308	  funext i
309	  by_cases h : ∃ k, f k = i
310	  · obtain ⟨k, rfl⟩ := h
311	    simp [clExtend_apply hf]
312	  · simp [clExtend, Function.extend_apply' _ _ _ h]
313	
314	/-- Formalization-only auxiliary: the extension is additive. -/
315	private theorem clExtend_add {K κ ι : Type*} [AddZeroClass K] {f : κ → ι}
316	    (hf : Function.Injective f) (u v : κ → K) :
317	    clExtend f (u + v) = clExtend f u + clExtend f v := by
318	  funext i
319	  by_cases h : ∃ k, f k = i
320	  · obtain ⟨k, rfl⟩ := h
321	    simp [clExtend_apply hf]
322	  · simp [clExtend, Function.extend_apply' _ _ _ h]
323	
324	/-- Formalization-only auxiliary: the extension commutes with scalars. -/
325	private theorem clExtend_smul {K κ ι : Type*} [Semiring K] {f : κ → ι}
326	    (hf : Function.Injective f) (c : K) (u : κ → K) :
327	    clExtend f (c • u) = c • clExtend f u := by
328	  funext i
329	  by_cases h : ∃ k, f k = i
330	  · obtain ⟨k, rfl⟩ := h
331	    simp [clExtend_apply hf]
332	  · simp [clExtend, Function.extend_apply' _ _ _ h]
333	
334	/-- Formalization-only auxiliary: transport a linear map of coefficient vectors
335	along an injective reindexing of registers; see `clExtend`.  Supports
336	`def:cl-func`, blueprint `blueprint/src/chapter/ch12_qpbt_games.tex:453-463`,
337	paper origin `references/qpbt-paper/05_conditionally_linear_functions.tex:35-57`. -/
338	private def clReindexLinear {K κ ι : Type*} [Field K] {f : κ → ι}
339	    (hf : Function.Injective f) (L : (κ → K) →ₗ[K] (κ → K)) :
340	    (ι → K) →ₗ[K] (ι → K) where
341	  toFun x := clExtend f (L (fun k => x (f k)))
342	  map_add' x y := by
343	    show clExtend f (L (fun k => (x + y) (f k))) =
344	      clExtend f (L (fun k => x (f k))) + clExtend f (L (fun k => y (f k)))
345	    have h : (fun k => (x + y) (f k)) =
346	        (fun k => x (f k)) + (fun k => y (f k)) := rfl
347	    rw [h, map_add, clExtend_add hf]
348	  map_smul' c x := by
349	    show clExtend f (L (fun k => (c • x) (f k))) =
350	      c • clExtend f (L (fun k => x (f k)))
351	    have h : (fun k => (c • x) (f k)) = c • (fun k => x (f k)) := rfl
352	    rw [h, map_smul, clExtend_smul hf]
353	
354	/-- Formalization-only auxiliary: transport a conditionally linear syntax tree
355	along an injective reindexing of registers; see `clExtend`.  Supports
356	`def:cl-func`, blueprint `blueprint/src/chapter/ch12_qpbt_games.tex:453-463`,
357	paper origin `references/qpbt-paper/05_conditionally_linear_functions.tex:35-57`. -/
358	private def clReindexTerm {K κ ι : Type*} [Field K] [Fintype κ] [DecidableEq κ]
359	    [Fintype ι] [DecidableEq ι] {f : κ → ι} (hf : Function.Injective f) :
360	    {ell : ℕ} → CondLinearTerm K (ι := κ) ell → CondLinearTerm K (ι := ι) ell
361	  | _, .zero => .zero
362	  | _, .succ S₁ L₁ h rest =>
363	      .succ (S₁.image f) (clReindexLinear hf L₁)
364	        (by
365	          intro x i hi
366	          by_cases hex : ∃ k, f k = i
367	          · obtain ⟨k, rfl⟩ := hex
368	            have hk : k ∉ S₁ := fun hk => hi (Finset.mem_image_of_mem f hk)
369	            show clExtend f (L₁ (fun j => x (f j))) (f k) = 0
370	            rw [clExtend_apply hf]
371	            exact h _ k hk
372	          · show clExtend f (L₁ (fun j => x (f j))) i = 0
373	            simp [clExtend, Function.extend_apply' _ _ _ hex])
374	        (fun y => clReindexTerm hf (rest (fun k => y (f k))))
375	
376	/-- Formalization-only auxiliary: the transported syntax tree is supported on
377	any register containing the image of the original support. -/
378	private theorem clReindexTerm_supportedOn {K κ ι : Type*} [Field K]
379	    [Fintype κ] [DecidableEq κ] [Fintype ι] [DecidableEq ι] {f : κ → ι}
380	    (hf : Function.Injective f) :
381	    ∀ {ell : ℕ} (t : CondLinearTerm K (ι := κ) ell) (S : Finset κ)
382	      (T : Finset ι), t.supportedOn S → S.image f ⊆ T →
383	      (clReindexTerm hf t).supportedOn T := by
384	  intro ell t
385	  induction t with
386	  | zero => intro S T _ _; trivial
387	  | succ S₁ L₁ hL rest ih =>
388	      intro S T hsupp hST
389	      obtain ⟨h1, h2⟩ := hsupp
390	      refine ⟨fun i hi => hST (Finset.image_subset_image h1 hi), fun y => ?_⟩
391	      refine ih (fun k => y (f k)) (S \ S₁) (T \ S₁.image f) (h2 _) ?_
392	      intro i hi
393	      obtain ⟨k, hk, rfl⟩ := Finset.mem_image.mp hi
394	      obtain ⟨hkS, hkS₁⟩ := Finset.mem_sdiff.mp hk
395	      refine Finset.mem_sdiff.mpr ⟨hST (Finset.mem_image_of_mem f hkS), ?_⟩
396	      intro hmem
397	      obtain ⟨k', hk', hk'eq⟩ := Finset.mem_image.mp hmem
398	      exact hkS₁ (hf hk'eq ▸ hk')
399	
400	/-- Formalization-only auxiliary: evaluation commutes with the transport of a
401	conditionally linear syntax tree along an injective reindexing. -/
402	private theorem clReindexTerm_eval {K κ ι : Type*} [Field K]
403	    [Fintype κ] [DecidableEq κ] [Fintype ι] [DecidableEq ι] {f : κ → ι}
404	    (hf : Function.Injective f) :
405	    ∀ {ell : ℕ} (t : CondLinearTerm K (ι := κ) ell) (x : ι → K),
406	      CondLinearTerm.eval (clReindexTerm hf t) x =
407	        clExtend f (CondLinearTerm.eval t (fun k => x (f k))) := by
408	  intro ell t
409	  induction t with
410	  | zero => intro x; exact (clExtend_zero hf).symm
411	  | succ S₁ L₁ hL rest ih =>
412	      intro x
413	      have hres : (fun k => coordinateRestriction (S₁.image f) x (f k)) =
414	          coordinateRestriction S₁ (fun k => x (f k)) := by
415	        funext k
416	        by_cases hk : k ∈ S₁
417	        · have hmem : f k ∈ S₁.image f := Finset.mem_image_of_mem f hk
418	          simp [coordinateRestriction, hk, hmem]
419	        · have hni : f k ∉ S₁.image f := by
420	            intro hmem
421	            obtain ⟨k', hk', hk'eq⟩ := Finset.mem_image.mp hmem
422	            exact hk (hf hk'eq ▸ hk')
423	          simp [coordinateRestriction, hk, hni]
424	      have hhead : clReindexLinear hf L₁ (coordinateRestriction (S₁.image f) x) =
425	          clExtend f (L₁ (coordinateRestriction S₁ (fun k => x (f k)))) := by
426	        show clExtend f (L₁ (fun k => coordinateRestriction (S₁.image f) x (f k))) = _
427	        rw [hres]
428	      have hcomp : (fun k => clReindexLinear hf L₁
429	            (coordinateRestriction (S₁.image f) x) (f k)) =
430	          L₁ (coordinateRestriction S₁ (fun k => x (f k))) := by
431	        rw [hhead]
432	        exact clExtend_comp hf _
433	      show clReindexLinear hf L₁ (coordinateRestriction (S₁.image f) x) +
434	          CondLinearTerm.eval (clReindexTerm hf (rest
435	            (fun k => clReindexLinear hf L₁
436	              (coordinateRestriction (S₁.image f) x) (f k)))) x =
437	        clExtend f (L₁ (coordinateRestriction S₁ (fun k => x (f k))) +
438	          CondLinearTerm.eval
439	            (rest (L₁ (coordinateRestriction S₁ (fun k => x (f k)))))
440	            (fun k => x (f k)))
441	      rw [hcomp, ih _ x, hhead, ← clExtend_add hf]
442	
443	/-- Formalization-only auxiliary: conditional linearity is preserved by an
444	injective reindexing of registers, the coordinates outside the image of the
445	reindexing being set to zero. -/
446	private theorem isCondLinearOn_reindex {K κ ι : Type*} [Field K]
447	    [Fintype κ] [DecidableEq κ] [Fintype ι] [DecidableEq ι] {f : κ → ι}
448	    (hf : Function.Injective f) {ell : ℕ} {L : (κ → K) → (κ → K)}
449	    (h : IsCondLinearOn K Finset.univ ell L) :
450	    IsCondLinearOn K Finset.univ ell
451	      (fun x => clExtend f (L (fun k => x (f k)))) := by
452	  obtain ⟨t, hsupp, hval⟩ := h
453	  refine ⟨clReindexTerm hf t,
454	    clReindexTerm_supportedOn hf t Finset.univ Finset.univ hsupp
455	      (Finset.subset_univ _), ?_⟩
456	  funext x
457	  rw [clReindexTerm_eval hf t x, hval]
458	
459	/-- Formalization-only auxiliary: the point projection of the ambient low-degree
460	coefficient space, presented as a linear map.  It is the map `L_Point` of
461	`def:ld-question-distribution`, blueprint `ch13_qpbt_test.tex:38-49`, paper
462	origin `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`. -/
463	private def ldPointProjection (P : LdParams) :
464	    LdSpace P →ₗ[ScalarQ P] LdSpace P where
465	  toFun z := ldPointCL P z
466	  map_add' x y := by
467	    funext i
468	    rcases i with (j | u) | j <;> simp [ldPointCL]
469	  map_smul' c x := by
470	    funext i
471	    rcases i with (j | u) | j <;> simp [ldPointCL]
472	
473	/-- Formalization-only auxiliary: the point map of the low-degree question
474	distribution is conditionally linear of level one, as asserted for `L_Point` in
475	`def:ld-question-distribution`, blueprint
476	`blueprint/src/chapter/ch13_qpbt_test.tex:38-49`, paper origin
477	`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.
478	It is recorded here because only the Pauli reindexing uses it. -/
479	private theorem isCondLinear_ldPointCL (P : LdParams) :
480	    IsCondLinearOn (ScalarQ P) Finset.univ 1 (ldPointCL P) :=
481	  isCondLinearOn_one_of_linear (ldPointProjection P)
482	
483	/-- Formalization-only auxiliary: the type-4 projection of the ambient Pauli
484	coefficient space, presented as a linear map; see `pauliSharedProjection` and
485	`def:pauli-question-distribution`, blueprint `ch13_qpbt_test.tex:285-329`,
486	paper origin `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:964-1120`. -/
487	private def pauliSharedProjectionLinear (P : AdmissibleParams) :
488	    PauliSpace P →ₗ[PauliScalar P] PauliSpace P where
489	  toFun z := pauliSharedProjection z
490	  map_add' x y := by
491	    funext i
492	    rcases i with ((((j | j) | u) | j) | u) | u <;> simp [pauliSharedProjection]
493	  map_smul' c x := by
494	    funext i
495	    rcases i with ((((j | j) | u) | j) | u) | u <;> simp [pauliSharedProjection]
496	
497	/-- Formalization-only auxiliary: the inclusion of the low-degree register index
498	into the ambient Pauli register index selected by a basis.  It realizes the
499	natural embedding of the range of the low-degree maps described in
500	`def:pauli-question-distribution`, blueprint `ch13_qpbt_test.tex:285-329`,
501	paper origin `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:964-1120`. -/
502	private def pauliLdIndex (P : AdmissibleParams) (W : PauliKind) :
503	    LdIndex P.toLdParams → PauliIndex P
504	  | .inl (.inl j) =>
505	      match W with
506	      | .X => .inl (.inl (.inl (.inl (.inl j))))
507	      | .Z => .inl (.inl (.inl (.inl (.inr j))))
508	  | .inl (.inr _) => .inl (.inl (.inl (.inr ())))
509	  | .inr j => .inl (.inl (.inr j))
510	
511	/-- Formalization-only auxiliary: distinct low-degree registers are sent to
512	distinct ambient Pauli registers; see `pauliLdIndex`. -/
513	private theorem pauliLdIndex_injective (P : AdmissibleParams) (W : PauliKind) :
514	    Function.Injective (pauliLdIndex P W) := by
515	  intro a b hab
516	  cases W <;> rcases a with (j | u) | j <;> rcases b with (j' | u') | j' <;>
517	    simp_all [pauliLdIndex]
518	
519	/-- Formalization-only auxiliary: reading the low-degree register out of an
520	ambient Pauli vector is restriction along `pauliLdIndex`; see
521	`def:pauli-question-distribution`, blueprint `ch13_qpbt_test.tex:285-329`,
522	paper origin `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:964-1120`. -/
523	private theorem pauliToLd_eq (P : AdmissibleParams) (W : PauliKind)
524	    (z : PauliSpace P) :
525	    pauliToLd P W z = fun k => z (pauliLdIndex P W k) := by
526	  funext k
527	  rcases k with (j | u) | j <;> cases W <;> rfl
528	
529	/-- Formalization-only auxiliary: writing a low-degree vector into the ambient
530	Pauli registers is extension along `pauliLdIndex`; see
531	`def:pauli-question-distribution`, blueprint `ch13_qpbt_test.tex:285-329`,
532	paper origin `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:964-1120`. -/
533	private theorem embedLd_eq (P : AdmissibleParams) (W : PauliKind)
534	    (w : LdSpace P.toLdParams) :
535	    embedLd P W w = clExtend (pauliLdIndex P W) w := by
536	  have hf := pauliLdIndex_injective P W
537	  funext i
538	  rcases i with ((((j | j) | u) | j) | u) | u
539	  · cases W
540	    · exact (clExtend_apply hf w (Sum.inl (Sum.inl j))).symm
541	    · exact (clExtend_eq_zero_of_not_mem _ w _ (by
542	        rintro ((j' | u') | j') <;> simp [pauliLdIndex])).symm
543	  · cases W
544	    · exact (clExtend_eq_zero_of_not_mem _ w _ (by
545	        rintro ((j' | u') | j') <;> simp [pauliLdIndex])).symm
546	    · exact (clExtend_apply hf w (Sum.inl (Sum.inl j))).symm
547	  · exact (clExtend_apply hf w (Sum.inl (Sum.inr ()))).symm
548	  · exact (clExtend_apply hf w (Sum.inr j)).symm
549	  · exact (clExtend_eq_zero_of_not_mem _ w _ (by
550	      intro k
551	      cases W <;> rcases k with (j' | u') | j' <;> simp [pauliLdIndex])).symm
552	  · exact (clExtend_eq_zero_of_not_mem _ w _ (by
553	      intro k
554	      cases W <;> rcases k with (j' | u') | j' <;> simp [pauliLdIndex])).symm
555	
556	/-- Formalization-only auxiliary: the typed Pauli point, axis-line, and
557	diagonal-line maps are the corresponding low-degree maps reindexed along
